const q = $input.item.json.query || {};
const verifyToken = $env.META_VERIFY_TOKEN;
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === verifyToken) {
  return { json: { challenge: q['hub.challenge'] } };
}
return { json: { challenge: 'verification-failed' } };

const q = $input.item.json.query || {};
const verifyToken = $env.WHATSAPP_VERIFY_TOKEN;
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === verifyToken) {
  return { json: { challenge: q['hub.challenge'] } };
}
return { json: { challenge: 'verification-failed' } };

// Detects which channel sent this webhook by payload shape and produces one common object.
const body = $input.item.json.body || $input.item.json;
let out = { channel: null, external_id: null, text: '', contact_name: '', phone: '', postcode: '', interest: '', ai_provider: '' };

if (body.message && body.message.chat && body.message.chat.id) {
  // Telegram
  out.channel = 'telegram';
  out.external_id = 'telegram:' + body.message.chat.id;
  out.text = body.message.text || '';
  out.contact_name = [body.message.from.first_name, body.message.from.last_name].filter(Boolean).join(' ');
} else if (body.entry && body.entry[0] && body.entry[0].messaging) {
  // Meta Messenger / Instagram DM (same webhook shape)
  const m = body.entry[0].messaging[0];
  const isInstagram = !!body.entry[0].id && body.object === 'instagram';
  out.channel = isInstagram ? 'instagram' : 'meta';
  out.external_id = (isInstagram ? 'instagram:' : 'messenger:') + m.sender.id;
  out.text = (m.message && m.message.text) || '';
} else if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0].value.messages) {
  // WhatsApp Cloud API
  const v = body.entry[0].changes[0].value;
  const msg = v.messages[0];
  out.channel = 'whatsapp';
  out.external_id = 'whatsapp:' + msg.from;
  out.text = (msg.text && msg.text.body) || '';
  const contact = (v.contacts || [])[0];
  out.contact_name = contact ? contact.profile.name : '';
} else {
  // Website widget - our own JSON shape: { session_id, text, name, phone?, postcode?, interest? }
  // The quote form sends phone/postcode/interest on first submit; the chat bubble sends text only.
  out.channel = 'website';
  out.external_id = 'website:' + body.session_id;
  out.text = body.text || '';
  out.contact_name = body.name || '';
  out.phone = body.phone || '';
  out.postcode = body.postcode || '';
  out.interest = body.interest || '';
  out.ai_provider = body.ai_provider || '';
}

return { json: out };

const lead = $('Normalize & Unify').item.json;
const hs = $json.results && $json.results[0];
const contactId = hs ? hs.id : null;

const knownFromForm = {};
if (lead.phone) knownFromForm.phone = lead.phone;
if (lead.postcode) knownFromForm.zip = lead.postcode;
if (lead.interest) knownFromForm.job_type_hint = lead.interest;
const known = { ...knownFromForm, ...(hs ? hs.properties : {}) };

const systemPrompt = `You are the intake assistant for ${$env.BUSINESS_NAME}, an AU roofing and solar installation company. You are messaging directly with a potential customer over ${lead.channel}. Be warm, concise (2-3 sentences max per reply), and use plain Australian English - no corporate language.

Your job each turn:
1. Read what's already known about this lead (below) and their latest message.
2. Ask for ONE missing piece of information at a time - never a long questionnaire.
3. Once you have suburb, job type, urgency, and owner-occupier status, you have enough to score the lead.
4. Score HOT if there is active leak/storm damage, or the lead is ready to book this week. Score WARM if they are a genuine prospect within 3 months. Score COLD if they are researching or more than 3 months out. Score UNQUALIFIED if they are a renter with no owner involvement, or outside the service area.
5. Set ready_to_book=true only once job_type, suburb and urgency are known AND the lead has agreed to book an inspection/quote.
6. Set escalate_to_human=true if: the job sounds like a full re-roof or solar+battery combo (high value), you are not confident answering something, or the lead is upset or complaining.
7. If the lead came from the website or another channel with no ongoing chat session, ask once whether Telegram, WhatsApp or SMS is best for follow-up, and capture whatever contact detail that needs (phone number for SMS).
8. Always call the capture_lead tool with your update, including the exact reply_to_lead text to send back.

Known so far: ${JSON.stringify(known)}
Service area postcodes: ${$env.SERVICE_POSTCODES}
Current STC rebate note (use once, naturally, if job_type includes solar): "${$env.STC_MESSAGE}"`;

// ---- Provider dispatch ----
// The website can request a provider via its "AI model" setting (sent as lead.ai_provider);
// every other channel (Telegram/FB/IG/WhatsApp) uses the server-side default. Whichever
// provider runs, its API key stays in n8n's env vars - it never touches the browser.
const provider = (lead.ai_provider || $env.AI_PROVIDER_DEFAULT || 'anthropic').toLowerCase();

// Same tool, described three ways - each provider's function-calling schema differs.
const toolProps = {
  full_name: 'string', suburb: 'string', postcode: 'string', owner_occupier: 'boolean',
  job_type: 'string', urgency: 'string', roof_or_bill_details: 'string',
  finance_interest: 'boolean', timeframe: 'string', lead_score: 'string',
  ready_to_book: 'boolean', escalate_to_human: 'boolean', reply_to_lead: 'string'
};
const enums = {
  job_type: ['repair','restoration','reroof','solar','solar_battery','unknown'],
  urgency: ['emergency','planning','unknown'],
  lead_score: ['hot','warm','cold','unqualified']
};
const required = ['lead_score','ready_to_book','escalate_to_human','reply_to_lead'];
const toolDescription = "Record or update this lead's qualification details based on the conversation so far.";

let url, header1Name, header1Value, header2Name, header2Value, body;

if (provider === 'gemini') {
  const model = $env.GEMINI_MODEL || 'gemini-2.5-flash';
  url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  header1Name = 'x-goog-api-key'; header1Value = $env.GOOGLE_AI_API_KEY;
  header2Name = 'X-Unused'; header2Value = '';
  const properties = {};
  for (const [k, t] of Object.entries(toolProps)) {
    properties[k] = { type: t.toUpperCase() };
    if (enums[k]) properties[k].enum = enums[k];
  }
  body = {
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: lead.text }] }],
    tools: [{ functionDeclarations: [{ name: 'capture_lead', description: toolDescription, parameters: { type: 'OBJECT', properties, required } }] }],
    toolConfig: { functionCallingConfig: { mode: 'ANY', allowedFunctionNames: ['capture_lead'] } }
  };
} else if (provider === 'grok') {
  const model = $env.GROK_MODEL || 'grok-4-0709';
  url = 'https://api.x.ai/v1/chat/completions';
  header1Name = 'Authorization'; header1Value = 'Bearer ' + $env.XAI_API_KEY;
  header2Name = 'X-Unused'; header2Value = '';
  const properties = {};
  for (const [k, t] of Object.entries(toolProps)) {
    properties[k] = { type: t };
    if (enums[k]) properties[k].enum = enums[k];
  }
  body = {
    model,
    messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: lead.text }],
    tools: [{ type: 'function', function: { name: 'capture_lead', description: toolDescription, parameters: { type: 'object', properties, required } } }],
    tool_choice: { type: 'function', function: { name: 'capture_lead' } }
  };
} else {
  url = 'https://api.anthropic.com/v1/messages';
  header1Name = 'x-api-key'; header1Value = $env.ANTHROPIC_API_KEY;
  header2Name = 'anthropic-version'; header2Value = '2023-06-01';
  const properties = {};
  for (const [k, t] of Object.entries(toolProps)) {
    properties[k] = { type: t };
    if (enums[k]) properties[k].enum = enums[k];
  }
  body = {
    model: 'claude-sonnet-5',
    max_tokens: 600,
    system: systemPrompt,
    messages: [{ role: 'user', content: lead.text }],
    tools: [{ name: 'capture_lead', description: toolDescription, input_schema: { type: 'object', properties, required } }],
    tool_choice: { type: 'tool', name: 'capture_lead' }
  };
}

return { json: { lead, known, contactId, provider, url, header1Name, header1Value, header2Name, header2Value, body: JSON.stringify(body) } };

const lead = $('Normalize & Unify').item.json;
const prompt = $('Build AI Request').item.json;
const provider = prompt.provider;

let data;
try {
  if (provider === 'gemini') {
    const parts = (($json.candidates || [])[0] || {}).content?.parts || [];
    const fc = parts.find(p => p.functionCall);
    data = fc ? fc.functionCall.args : null;
  } else if (provider === 'grok') {
    const toolCall = (($json.choices || [])[0] || {}).message?.tool_calls?.[0];
    data = toolCall ? JSON.parse(toolCall.function.arguments) : null;
  } else {
    const toolUse = ($json.content || []).find(c => c.type === 'tool_use');
    data = toolUse ? toolUse.input : null;
  }
} catch (e) {
  data = null;
}

if (!data) {
  data = { lead_score: 'cold', ready_to_book: false, escalate_to_human: true, reply_to_lead: "Thanks, one of our team will be in touch shortly." };
}

return { json: {
  channel: lead.channel,
  external_id: lead.external_id,
  contact_name: data.full_name || lead.contact_name,
  contactId: prompt.contactId,
  suburb: data.suburb || '',
  postcode: data.postcode || '',
  owner_occupier: !!data.owner_occupier,
  job_type: data.job_type || 'unknown',
  urgency: data.urgency || 'unknown',
  roof_or_bill_details: data.roof_or_bill_details || '',
  finance_interest: !!data.finance_interest,
  timeframe: data.timeframe || '',
  lead_score: data.lead_score || 'cold',
  ready_to_book: !!data.ready_to_book,
  escalate_to_human: !!data.escalate_to_human,
  reply_to_lead: data.reply_to_lead,
  ai_provider_used: provider
} };

const lead = $('Parse AI Response').item.json;
const hsId = $json.id;
return { json: { ...lead, contactId: hsId } };

// Free-text detail (owner-occupier, bill/roof notes, timeframe) goes on a Note engagement,
// not a custom property - keeps us inside HubSpot Free's 10-custom-property cap.
const d = $json;
const noteBody = `Owner-occupier: ${d.owner_occupier}\nDetails: ${d.roof_or_bill_details}\nTimeframe: ${d.timeframe}\nLast message: ${$('Normalize & Unify').item.json.text}`;
return { json: { ...d, noteBody } };
